        "recorded_at": "Feb 01, 2026, 20:29:37",
        "source_ref": "results/medium_dev/williams_native_prefix5_20261028_v3/users/1b846c59-456e-9550-dffd-4d23f1eca81f/session_005/input.json#/raw_dialogue/30/content"
